package com.example.rpg.repository;
import com.example.rpg.domain.*; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Repository; import java.nio.file.*; import java.util.*;
/** File profile demonstrates replacing the repository without changing service code. */
@Repository @Profile("file") class FileUserRepository implements UserRepository { private final Map<String,UserAccount> users=new HashMap<>(); private long next=1; public FileUserRepository(){ } public synchronized UserAccount save(UserAccount u){UserAccount c=new UserAccount(u.id()==0?next++:u.id(),u.username(),u.passwordHash());users.put(c.username(),c);return c;} public synchronized Optional<UserAccount> findByUsername(String n){return Optional.ofNullable(users.get(n));} }
/** File persistence is intentionally a separate adapter behind CharacterRepository. */
@Repository @Profile("file") class FileCharacterRepository implements CharacterRepository { private final Path path; private final ObjectMapper mapper=new ObjectMapper(); private final Map<Long,SaveSnapshot> saves=new HashMap<>(); FileCharacterRepository(@Value("${rpg.file.path}")String p){path=Path.of(p);load();} public synchronized void save(SaveSnapshot s){saves.put(s.userId(),s);try{Files.createDirectories(path.getParent());mapper.writeValue(path.toFile(),saves.values());}catch(Exception e){throw new IllegalStateException("save failed",e);}} public synchronized Optional<SaveSnapshot> findByUserId(long id){return Optional.ofNullable(saves.get(id));} private void load(){if(!Files.exists(path))return;try{for(SaveSnapshot s:mapper.readValue(path.toFile(),SaveSnapshot[].class))saves.put(s.userId(),s);}catch(Exception e){throw new IllegalStateException("load failed",e);}} }
